`build_hierarchy(rows)` accepts a list of dictionaries with `id`, `parent_id`, `label`, and `metadata`. IDs must be unique non-empty strings; `parent_id` must be `None` or a string naming an existing row; labels must be strings; metadata must be dictionaries. Extra fields are ignored. Reject self-parenting, longer cycles, missing parents, and malformed values with `ValueError`; a non-list input or non-dictionary row raises `TypeError`.

Return root nodes in input order, with children in input order. Each output node has `id`, `label`, `metadata`, and `children`. An empty input returns an empty list. Neither the output nor later mutations of input metadata may affect the other, including nested values.

```python
from copy import deepcopy


def build_hierarchy(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    indexed = {}
    order = []
    for row in rows:
        if not isinstance(row, dict):
            raise TypeError("each row must be a dictionary")
        if not {"id", "parent_id", "label", "metadata"}.issubset(row):
            raise ValueError("row is missing a required field")
        ident = row["id"]
        parent = row["parent_id"]
        if not isinstance(ident, str) or not ident:
            raise ValueError("id must be a non-empty string")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent_id must be a string or None")
        if not isinstance(row["label"], str) or not isinstance(row["metadata"], dict):
            raise ValueError("invalid label or metadata")
        if ident in indexed:
            raise ValueError("duplicate id")
        indexed[ident] = row
        order.append(ident)

    for ident in order:
        parent = indexed[ident]["parent_id"]
        if parent is not None and parent not in indexed:
            raise ValueError("missing parent")
        seen = set()
        current = ident
        while current is not None:
            if current in seen:
                raise ValueError("cycle detected")
            seen.add(current)
            current = indexed[current]["parent_id"]

    nodes = {
        ident: {
            "id": ident,
            "label": indexed[ident]["label"],
            "metadata": indexed[ident]["metadata"],
            "children": [],
        }
        for ident in order
    }
    roots = []
    for ident in order:
        parent = indexed[ident]["parent_id"]
        if parent is None:
            roots.append(nodes[ident])
        else:
            nodes[parent]["children"].append(nodes[ident])
    return roots
```

